  servicosVeiculo: { nome: "ServicosVeiculo", header: SERVICOS_VEICULO_HEADER, colunas: "I", toRow: servicoVeiculoToRow },
  semParar: { nome: "SemParar", header: SEM_PARAR_HEADER, colunas: "H", toRow: semPararToRow },
  seguro: { nome: "Seguro", header: SEGURO_HEADER, colunas: "L", toRow: seguroToRow },
  semPararOutros: { nome: "SemPararOutros", header: SEM_PARAR_OUTROS_HEADER, colunas: "E", toRow: semPararOutroToRow },
  financeiroPessoal: { nome: "FinanceiroPessoal", header: FINANCEIRO_PESSOAL_HEADER, colunas: "L", toRow: financeiroPessoalToRow },
  multas: { nome: "Multas", header: MULTAS_HEADER, colunas: "J", toRow: multaToRow },
