                  const fimDate = new Date(Number(m.mes.slice(0, 4)), Number(m.mes.slice(5, 7)), 0);
                  setDashboardGeralPeriodStart(inicioMes);
                  setDashboardGeralPeriodEnd(fimDate.toISOString().slice(0, 10));
