                    {b.descricao}
                    {b.observacao && /^Gerado automaticamente/.test(b.observacao) && (() => {
                      const m = b.observacao.match(/(\d{2}\/\d{2}\/\d{4})$/);
                      return m ? <div style={{ fontSize: 9, color: "#9AA5B1" }}>📅 Realizado em {m[1]}</div> : null;
                    })()}
